@startuml

class SensorController {
  + username : string
  + password : string
}

class Apartment {
  + address : string
  + inhabitants : List<User>
}

class User {
  + username : string
  + password : string
  + isAdmin : boolean
}

class Room {
  + description : string
  + sensors : List<Sensor>
}

abstract class Sensor {
  + vendorId : int
  + description : string
  + unit : string
  + room : Room
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + counterReading : long
}

class Threshold {
  + value : float
  + sensor : Sensor
}

class EMonitor {
  + checkThresholds() : void
}

class AlertMessage {
  + message : string
  + emailAddress : string
}

class Value {
  + timestamp : datetime
  + floatValue : float
}

SensorController "1" -- "*" Apartment
Apartment "1" -- "*" User
User "0..*" -- "1" SensorController
Room "1" -- "* sensors" Sensor
Sensor "1" -- "1 room" Room
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor
Sensor "1" -- "0..1 threshold" Threshold
EMonitor ..> SensorController : checks thresholds
AlertMessage ..> EMonitor : sent by E-Monitor
Value "0..*" -- "1 sensor" Sensor

@enduml

